  // ── buildPartVerificationChecklistItems() ────────────────────
  pvc_contactor_1: { en: "Verify line voltage into the contactor.", es: "Verifica el voltaje de línea que entra al contactor." },
  pvc_contactor_2: { en: "Verify coil voltage when the call is present.", es: "Verifica el voltaje de la bobina cuando hay una llamada activa." },
  pvc_contactor_3: { en: "Check line-to-load contact drop under load.", es: "Revisa la caída de voltaje de línea a carga en los contactos bajo carga." },
  pvc_contactor_4: { en: "Inspect for pitted contacts, overheated wires, and loose lugs.", es: "Inspecciona si hay contactos picados, cables sobrecalentados, y terminales sueltas." },
  pvc_note_contactor: { en: "Do not replace the contactor without checking whether compressor/fan load caused the failure.", es: "No reemplaces el contactor sin verificar si la carga del compresor/ventilador causó la falla." },
  pvc_capacitor_1: { en: "Test actual capacitance and compare against the rated µF.", es: "Prueba la capacitancia real y compárala con los µF nominales." },
  pvc_capacitor_2: { en: "Verify supply voltage to the motor/compressor circuit.", es: "Verifica el voltaje de suministro al circuito del motor/compresor." },
  pvc_capacitor_3: { en: "Check amp draw on the connected motor/compressor.", es: "Revisa el consumo de amperaje del motor/compresor conectado." },
  pvc_capacitor_4: { en: "Inspect for swelling, oil leakage, or overheated terminals.", es: "Inspecciona si hay hinchazón, fuga de aceite, o terminales sobrecalentadas." },
  pvc_note_capacitor: { en: "A failed capacitor can be the symptom of a weak motor or compressor.", es: "Un capacitor fallido puede ser el síntoma de un motor o compresor débil." },
  pvc_cond_fan_1: { en: "Verify proper voltage to the fan motor.", es: "Verifica el voltaje correcto al motor del ventilador." },
  pvc_cond_fan_2: { en: "Check fan rotation and blade condition.", es: "Revisa la rotación del ventilador y la condición de las aspas." },
  pvc_cond_fan_3: { en: "Compare motor amp draw to expected operation.", es: "Compara el consumo de amperaje del motor con la operación esperada." },
  pvc_cond_fan_4: { en: "Inspect the coil for dirt and confirm heat rejection is not the root issue.", es: "Inspecciona el serpentín por suciedad y confirma que el rechazo de calor no sea la causa raíz." },
  pvc_note_cond_fan_head: { en: "High head relative to ambient supports heat-rejection verification before condemning the motor.", es: "La descarga alta en relación al ambiente respalda verificar el rechazo de calor antes de condenar el motor." },
  pvc_evap_fan_1: { en: "Verify fan operation and correct rotation.", es: "Verifica la operación del ventilador y la rotación correcta." },
  pvc_evap_fan_2: { en: "Check voltage at the motor and any speed/module output.", es: "Revisa el voltaje en el motor y cualquier salida de velocidad/módulo." },
  pvc_evap_fan_3: { en: "Inspect blade/wheel condition and airflow path.", es: "Inspecciona la condición de la aspa/rueda y la ruta de flujo de aire." },
  pvc_evap_fan_4: { en: "Check for ice, drain problems, and defrost issues affecting airflow.", es: "Revisa si hay hielo, problemas de drenaje, y problemas de descongelamiento que afecten el flujo de aire." },
  pvc_note_evap_fan_split: { en: "Weak split supports airflow/fan verification before deeper refrigerant-side part swaps.", es: "Un split débil respalda verificar flujo de aire/ventilador antes de reemplazar partes más profundas del lado de refrigerante." },
  pvc_defrost_heater_1: { en: "Ohm the heater for continuity with power isolated.", es: "Mide en ohms el calentador para continuidad con la energía aislada." },
